frag:
#version 300 es
precision highp float;
uniform vec2 u_res;
uniform float u_time;
out vec4 fragColor;

void main() {
  vec2 uv = gl_FragCoord.xy / u_res;
  vec2 p = (gl_FragCoord.xy - 0.5 * u_res) / min(u_res.x, u_res.y);
  float t = u_time * 0.2;
  vec2 c = vec2(sin(t), cos(t * 0.7)) * 0.4;
  float w = sin(p.x * 2.4 + t * 1.3) + sin(p.y * 3.1 - t) + sin(length(p + c) * 5.0 - t * 2.0);
  w = w / 6.0 + 0.5;
  vec3 deep = vec3(0.05, 0.03, 0.16);
  vec3 violet = vec3(0.35, 0.27, 0.91);
  vec3 rose = vec3(0.98, 0.52, 0.68);
  vec3 col = mix(deep, violet, smoothstep(0.15, 0.6, w));
  col = mix(col, rose, smoothstep(0.55, 0.95, w) * uv.y);
  fragColor = vec4(col, 1.0);
}
